  deeper:   0x1a3350,   // troughs
  mid:      0x5a89a8,   // light band on wave face
  foam:     0xeef0e9,   // foam white
  waterLt:  0x8aa6b8,   // light water patches
  fujiDark: 0x33465c,
  fujiMid:  0x7d8b96,
  fujiSnow: 0xf7f6f1,
  hull:     0xd8896a,   // salmon boat hull
  hullDark: 0x22384f,   // gunwale
  figure:   0xefece2,
};

const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('c'), antialias: true });
