renderer.setSize(innerWidth, innerHeight);
renderer.setClearColor(C.paper);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(C.paper, 26, 46);
const camera = new THREE.PerspectiveCamera(45, innerWidth/innerHeight, 0.1, 100);
camera.position.set(0.6, 7.9, 15.2);
camera.lookAt(0.2, 2.2, 0);

// ---- wave surface (shared by geometry + foam dots) ----------------------
// v: 0 = waterline, 0.5 = crest, 1 = end of the foam curl (hanging mid-face,
// like the print's claw, so the broad indigo face stays visible below it)
const waveH = x => 3.0 + 4.4 * Math.exp(-Math.pow((x + 2) / 3.2, 2)); // tall left, lower right swell
function ySurf(x, v) {
  const H = waveH(x);
  if (v < 0.5) return H * (v / 0.5);
  const th = (v - 0.5) * Math.PI; // 0..pi/2 curl
  return H * 0.70 + H * 0.30 * Math.cos(th);
}
function zSurf(x, v) {
  if (v < 0.5) return 2.2 + 0.35 * (v / 0.5) + 0.5 * Math.sin(x * 0.4) * v;
  const th = (v - 0.5) * Math.PI;
  return 2.55 + 1.55 * Math.sin(th) + 0.5 * Math.sin(x * 0.4) * v;
}

function waveColor(v) {
  if (v < 0.10) return C.deeper;
  if (v < 0.42) return C.deep;
  if (v < 0.55) return C.mid;
  return C.foam; // the foam claw on the crest/curl
}

function buildWave(len, x0, z0, ny, nx) {
  const pos = [], col = [], idx = [];
  for (let i = 0; i <= nx; i++) {
    const x = x0 + (i / nx) * len;
    for (let j = 0; j <= ny; j++) {
      const v = j / ny;
      pos.push(x, ySurf(x, v), z0 + zSurf(x, v));
      const c = new THREE.Color(waveColor(v));
      col.push(c.r, c.g, c.b);
    }
  }
  for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
    const a = i * (ny + 1) + j, b = a + ny + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

